SELECT COUNT(CASE WHEN "t0"."order_date" >= TIMESTAMP '2026-07-31 17:00:00' AND "t0"."order_date" < TIMESTAMP '2026-08-31 17:00:00' THEN 1 END) AS "order_count" FROM "sales"."orders" AS "t0" INNER JOIN "crm"."customers" AS "t1" ON "t0"."customer_id" = "t1"."customer_id" WHERE ("t0"."status" = 'DONE') AND ("t1"."segment" = 'VIP') AND ("t0"."order_date" >= TIMESTAMP '2026-07-31 17:00:00' AND "t0"."order_date" < TIMESTAMP '2026-08-31 17:00:00')
